        "whyItMatters": "DSS-23 把地面排班、维护和信号处理重新放回太空科学链条。新天线能通过并行和阵列缓解任务竞争，却不等于每个任务自动获得更多时间；网络仍要在导航、指令、紧急事件与科学下载之间调度。评估基础设施效果，应追踪可用小时、阵列使用、维护停机和任务积压，而不只统计天线数量。",
