        "summary": "Ellen Harvey 是一位以绘画、装置和公共介入研究记忆、风景与纪念方式的当代艺术家。University of South Florida Contemporary Art Museum 新展《PICTURE(SQUE)》汇集她 1999 至 2025 年的四组作品：观众想重访却已不存在的地点、Florida 湿地与城市、被涂写的街景，以及图书馆访客想象的乌托邦。",
