        "happened": "这场二十六年作品调查于 8 月 24 日开放，将持续至 2027 年 3 月 6 日。展览首次把关于失去与关于未来的两套持续征集并置，使公众提交的消失地点不只成为哀悼清单，也与‘怎样才算乌托邦’的愿望发生比较。",
