          "语言定位任务比较阅读句子与可发音无意义词串。执行控制定位任务要求记住三乘四网格中的八个困难位置或四个简单位置。",
          "语言网络在两组中的激活范围、左半球侧化、选择性与内部功能连接相似，语言反应强度随年龄仅略有增加。",
          "较年长组的 multiple demand network 激活更弱、显著体素更少、激活峰位置更可变，内部功能连接也较低。",
          "听故事的子样本中，两组对陌生词和不寻常语法结构都出现相似的语言网络反应增强。",
