        "sourceName": "Nature Communications／MIT News／Preserved language network in older brains",
        "sourceUrl": "https://www.nature.com/articles/s41467-026-76598-x",
        "sourceDate": "论文与 MIT 报道 2026-08-24；Nature Communications 17, 8573",
        "whyItMatters": "同一批参与者中的网络对照说明，年龄差异不是一股均匀扫过全脑的下降。专门处理积累性语言知识的系统与灵活调用资源的执行系统可以呈现不同轨迹，这比‘老人脑力衰退’的总括说法更接近证据。",
        "importance": "这不表示找词困难或神经疾病不存在，也不能从横截面数据证明某个网络为何更有韧性。它提供的是更精确的照护与研究起点：评估老年人的语言、记忆和执行功能时，不应把一项困难自动外推到所有认知能力。",
        "creatorAngle": "可以把同一参与者的句子、无意义词串、四位置与八位置任务画成四层网络图，分别标出激活范围、强度、侧化与连接；再追踪四十一至八十岁内部是否存在不同阶段，而不是只比较两个大组平均值。"
