        "summary": "220P/McNaught 是一颗周期超过五年、轨道位于 Mars 与 Jupiter 之间的彗星，平时暗到需要望远镜。NASA Astronomy Picture of the Day 今日记录它在 2026 年两次意外爆发后比通常亮约两万倍，现可用双筒望远镜和长曝光相机观察。",
