        "summary": "文化心理学研究社会共享的习惯、意义和制度怎样与人的认知和行为相关。Jason Martens 今天出版的《Beyond Biology: How Culture Created You》面向普通读者，讨论语言、饮食、音乐和社会规范为何不仅表现差异，也可能与身体、偏好和健康分布一起变化。",
