        "summary": "美国寄养照护由儿童福利系统在家庭安全无法维持时安排儿童离家照护。一项覆盖六十个辖区的准实验研究发现，州级驱逐暂缓令持续实施的地区，与因住房不足、照护者无法应对和身体虐待而进入寄养照护的记录减少相关，但总进入数没有显著变化。",
