          "研究在 2011 至 2025 年间完成 11 个调查波次。",
          "轨迹模型识别出抵抗、亚阈值、中度持续、恢复和重度持续五种长期模式。",
          "十五年时有 190 人达到临床意义阈值，占 14.7%。",
          "前两年持续高分且继续上升者有 175 人，其中 72 人在十五年时仍超过阈值，占 41.1%。",
          "相较早期未持续高分组，症状上升组与十五年持续症状的调整优势比为 5.31。",
