        "happened": "MoMA 公布《Full Disclosure: The Edge of Information Design》，展览将于 9 月 27 日在免费开放的街层展厅开幕。它把历史流程图、个人数据日记、气候图像、贫困比较和调查性空间分析并置，并将六件新入藏作品放进博物馆的设计收藏脉络。",
