        "summary": "“工作锁定”指一个人想退休，却因收入、医疗保险或其他资源需要而不得不继续工作。美国五千余名五十岁以上劳动者的六年队列显示，这种状态很常见，并与较差的自评健康、抑郁症状、精神问题和较高体重状态持续相关。",
