        "happened": "《The Gerontologist》7 月 22 日在线发表研究，Harvard Chan 于 8 月 13 日进一步解释时间自主与健康的关系。研究使用 Health and Retirement Study 数据，把基线时的工作锁定与之后六年的多项身心健康结局比较，并控制人口、财务与行为因素。",
