        "summary": "MIT 的 Human-Environment Connection and Interaction Atlas 是一套把居住空间特征与心理体验相连的交互证据图谱。团队用文献与专家访谈整理照明、动线、隐私和可重构空间，帮助设计者追踪它们可能怎样影响长期隔离者的睡眠、自主感与社会连接。",
        "background": "月球或火星任务会让少数人在狭小、封闭且远离地球的环境中生活数月甚至数年。传统工程指标优先处理结构、质量和生命保障，但居住者无法像地面建筑用户那样轻易离开；空间设计因此也成为行为健康与团队协作的基础设施。",
