          "图谱借用 NASA 风险管理使用的有向无环图结构。",
          "团队整理了 14 类情绪或体验，包括焦虑、自主、好奇、疲劳、亲近与思乡。",
          "候选体验还参考了《Atlas of the Heart》所列的 87 种情绪与经验。",
          "照明路径连接睡眠、昼夜节律和工作表现。",
          "舱室动线与布局路径连接隐私、社交接触和团队表现。",
