        "summary": "妊娠糖尿病是孕期首次发现的血糖异常。对超过一百一十五万名美国商业保险参保者的病历研究发现，既往妊娠糖尿病与产后糖尿病前期、二型糖尿病、高血压、血脂异常、肥胖和心血管事件发生率升高相关。",
