          "中位随访时间为 2.4 年，四分位距为 1.6 至 3.8 年。",
          "二型糖尿病粗发生率每千人年为 9.9 对 1.0。",
          "糖尿病前期粗发生率每千人年为 12.9 对 2.5。",
          "血脂异常为 19.9 对 10.1，高血压为 13.9 对 8.1，肥胖为 26.3 对 15.2。",
          "调整后，二型糖尿病风险比为 10.02，糖尿病前期为 5.32，代谢综合征为 2.72。",
          "调整后，血脂异常风险比为 2.00，高血压为 1.76，肥胖为 1.75，复合心血管疾病为 1.28。",
