        "whyItMatters": "二型糖尿病、血脂、高血压、肥胖与心血管结局方向一致，说明分娩不能成为风险沟通和照护的终点；肾病结果则因事件少而不能被写成已经排除风险。可以画一条从孕期筛查到产后十年的照护时间线，把血糖、血压、血脂、体重、肾功能和保险连续性分开记录，再追踪哪些节点因为育儿、工作、交通或保障中断而消失。"
