        "background": "社区参与式研究让受影响社群参与问题设计、解释和传播，而不只作为被调查对象。此次项目从 2020 年开始，与湾区阿富汗社群合作，以英语或达里语访谈迁入美国的成年女性，并由双语研究者和社区成员复核语言与主题。",
