        "happened": "UC Davis 团队于 8 月 4 日发布研究说明，原始论文已于 7 月 7 日在线发表于《Psychological Medicine》。结果显示，睡眠在多类心理症状与后续成绩或社交困难之间承担的统计中介比例最高；屏幕时间在成绩路径中次之，而家庭经济和关系环境会调节部分路径。",
