        "title": "病毒控制相近时，少增两公斤也会改变治疗选择",
        "summary": "Opti-DOR 是一项在南非比较两种每日口服 HIV 初始治疗的随机试验。600 名参与者接受 doravirine 或常用的 dolutegravir 方案 48 周，两组病毒抑制相近，但前者的体重和体脂增幅较小。",
