          "参与者中约 69% 出生时指定为女性，超过 99% 被记录为 Black African，年龄中位数为 34 岁。",
          "48 周时，doravirine 组有 89.0% 达到每毫升低于 50 copies 的病毒抑制，对照组为 90.7%，差异符合非劣效标准。",
          "中位体重增加分别为 3.0 公斤与 5.0 公斤。体重增加至少 5% 的比例分别为 41.1% 与 56.8%。",
