        "happened": "Cedars-Sinai 与加拿大研究团队在《JAMA Network Open》发布近人群基础队列研究。团队分别估算阳性、普通阴性、意义不明变异和预测阴性者的乳腺癌及卵巢癌累计风险，并检验一级亲属癌症史如何改变风险。",
