          "91.1% 的患者原本计划纯母乳喂养，8.9% 计划母乳与配方奶混合。",
          "住院期间实际纯母乳喂养者占 71.0%。",
          "每八小时班次达到一次建议支持时，调整后的纯母乳喂养概率为 78%。完全没有支持记录时为 49%，支持比达到两倍时为 91%。",
