        "whyItMatters": "梦境记录与白天经历之间既有重合，也有明显的重新组合，因此梦更像是在加工近期经验，而不是把现实完整重播一遍。研究还发现，不同人的心智游移和睡眠状况会改变梦境报告的形式，这意味着解释一个梦时，不能脱离做梦者当时的生活与心理状态。",
