        "happened": "指引聚焦稳定接受性别肯定激素治疗至少六个月的成年人，覆盖检验参考区间、输血、尸检、组织学和病理信息学五个领域。它建议电子病历记录器官是否存在及手术日期，并在证据不足时允许双重报告参考区间。",
