          "另一团队用 VLT/ERIS、JWST/NIRCam 与 VLT/SPHERE 拼出 11 年基线，估计质量为木星的 2.4±0.6 倍、有效温度约 600 K。",
          "它约比系统内另外两颗已知行星暗 100 倍。β Pictoris 因此成为第二个拥有三颗以上直接成像行星的系统。"
